const w2rEsc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]||c));
type ComplejoPago={pagoTransferenciaDisponible?:boolean;pagoAlias?:string;pagoTitular?:string;pagoEntidad?:string;pagoInstrucciones?:string;whatsapp?:string};let w2rComplejo:ComplejoPago|null=null,w2rBusy=false;
const w2rMoney=(n:number,c='ARS')=>new Intl.NumberFormat('es-AR',{style:'currency',currency:c||'ARS',maximumFractionDigits:0}).format(Number(n||0));const w2rLongDate=(v:string)=>new Intl.DateTimeFormat('es-AR',{weekday:'long',day:'numeric',month:'long'}).format(new Date(v+'T12:00:00'));const w2rShortDate=(v:string)=>new Intl.DateTimeFormat('es-AR',{weekday:'short',day:'numeric',month:'short'}).format(new Date(v+'T12:00:00'));const w2rLabel=(s:string)=>({PENDIENTE:'Esperando seña',CONFIRMADA:'Confirmada',COMPLETADA:'Completada',CANCELADA:'Cancelada',EXPIRADA:'Expirada',AUSENTE:'Ausente'} as Record<string,string>)[s]||s;const w2rClass=(s:string)=>s.toLowerCase();const w2rUuid=(v:string)=>/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v);
