function w2rPayment(r:Reserva,history:boolean){if(!history&&r.pendiente)return[['Seña requerida',w2rMoney(r.importeSenia,r.moneda)],['Acreditado',w2rMoney(r.totalAcreditado,r.moneda)],['Falta para confirmar',w2rMoney(Math.max(0,r.importeSenia-r.totalAcreditado),r.moneda)]];if(!history&&r.confirmada)return[['Seña acreditada',w2rMoney(r.totalAcreditado,r.moneda)],['Saldo del turno',w2rMoney(r.saldoPendiente,r.moneda)],['Estado','Cancha asegurada']];if(['CANCELADA','EXPIRADA'].includes(r.estado))return[['Total de referencia',w2rMoney(r.precioTotal,r.moneda)],['Acreditado',w2rMoney(r.totalAcreditado,r.moneda)],['Estado de pago',r.totalAcreditado>0?'Con acreditaciones':'Sin cobros']];if(r.estado==='AUSENTE')return[['Total del turno',w2rMoney(r.precioTotal,r.moneda)],['Acreditado',w2rMoney(r.totalAcreditado,r.moneda)],['Estado administrativo','Ausencia registrada']];return[['Total del turno',w2rMoney(r.precioTotal,r.moneda)],['Acreditado',w2rMoney(r.totalAcreditado,r.moneda)],['Resultado','Turno finalizado']];}
